class Spaceship {
  #fuelLevel;
  publicFuelLevel;

  constructor(initialFuel) {
    this.#fuelLevel = initialFuel;
    this.publicFuelLevel = initialFuel;
  }

  refuel(amount) {
    if (amount > 0) {
      this.#fuelLevel += amount;
      this.publicFuelLevel = this.#fuelLevel;
    } else {
      console.warn("Refuel amount must be positive.");
    }
  }

  launch() {
    const fuelNeeded = 10;
    if (this.#fuelLevel >= fuelNeeded) {
      this.#fuelLevel -= fuelNeeded;
      this.publicFuelLevel = this.#fuelLevel;
      return `Launched! Current fuel: ${this.publicFuelLevel}`;
    } else {
      return `Not enough fuel to launch. Requires ${fuelNeeded} but has ${this.#fuelLevel}`;
    }
  }

  getFuelLevel() {
    return this.publicFuelLevel;
  }
}

